/* Retire the former Chirpy offline worker at its published URL. */
'use strict';

self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const scope = new URL(self.registration.scope);
    const stylesheet = new URL('assets/css/jekyll-theme-chirpy.css', scope);

    try {
      const names = await caches.keys();
      await Promise.all(names.filter((name) => name.startsWith('chirpy-')).map(async (name) => {
        const cache = await caches.open(name);
        const requests = await cache.keys();
        const paths = requests.map((request) => new URL(request.url));
        // Chirpy's cache names have no scope. Its two bootstrap resources
        // identify this site's cache without touching sibling project caches.
        const hasHome = paths.some((url) => url.origin === scope.origin && url.pathname === scope.pathname);
        const hasStylesheet = paths.some((url) => url.origin === stylesheet.origin && url.pathname === stylesheet.pathname);
        if (hasHome && hasStylesheet) await caches.delete(name);
      }));
    } finally {
      // Only retire this registration; other applications keep their workers.
      await self.registration.unregister();
    }
  })());
});

// No fetch handler: open pages continue using the network without a redirect.
